import fs from 'node:fs';import{gzipSync}from'node:zlib';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('tuning_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
function setup(sim,kind){}
function params(kind){return kind==='scale'?{rootNote:7,scaleName:'Minor',scaleMode:false}:kind==='system'?{name:'Custom',lowestNote:{note:2,deviation:5},highestNote:{deviation:-5,note:125},referencePitch:{frequency:442,note:69}}:kind==='notes'?{noteTunings:Array.from({length:128},(_,note)=>({note,deviation:(note%12)*10}))}:{name:'Custom'};}
const rows=[];for(const action of ['preview','apply']){const valid=action==='preview'?{name:'Custom'}:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of (action==='preview'?['name','lowestNote','highestNote','referencePitch','noteTunings','rootNote','scaleName','scaleMode']:Object.keys(valid))){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,0.5,1,100001,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}if(action==='preview'){for(const count of [0,127,128,129])cases.push({noteTunings:Array.from({length:count},(_,note)=>({note:note%128,deviation:0}))});for(const field of ['note','deviation','extra'])for(const value of [null,false,'1',-1201,-1,0,0.5,127,128,1200,1201,1e308]){const noteTunings=params('notes').noteTunings;noteTunings[0][field]=value;cases.push({noteTunings});}}for(const args of cases){const sim=new DeterministicLiveSimulator();setup(sim,'session-midi');const host=new McpHost(sim);let result;try{result=clean(await host[action==='preview'?'liveTuningPreviewAsync':'liveTuningApplyAsync'](1,args));}catch(e){result={error:e.message};}rows.push({action,args,result});}}
const workflows=[];for(const kind of ['name','scale','system','notes'])for(const scenario of ['normal','expire','epoch','identity-edit','source-content','null-prior','missing-prior','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-clamped','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-content','undo-epoch']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();setup(sim,kind);let fault='',fired=false,afterInvoke=false;if(scenario==='missing-identity')delete sim.state.set.objectIdentity;if(scenario==='null-prior'){sim.state.tuning.system.referencePitch=null;sim.state.tuning.scale.rootNote=null;}if(scenario==='missing-prior'){delete sim.state.tuning.system.referencePitch;delete sim.state.tuning.scale.rootNote;}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));if(i.operation==='tuning.read'){readFault();return sim.invoke(i);}const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&['apply-invalid-identity','apply-invalid-fingerprint'].includes(fault)){fired=true;result[fault.endsWith('identity')?'objectIdentity':'createdFingerprint']='';}if(!fired&&fault==='apply-clamped'){fired=true;if(kind==='scale')sim.state.tuning.scale.rootNote=5;else if(kind==='notes')sim.state.tuning.system.noteTunings[0].deviation=8;else sim.state.tuning.system.name='Manual';}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const args=params(kind);const preview=await host.liveTuningPreviewAsync(1,args);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveTuningApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.set.objectIdentity='other';if(scenario==='source-content')sim.state.tuning.system.name='Manual';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-identity')sim.state.set.objectIdentity='other';if(scenario==='undo-other-content'){if(kind==='scale')sim.state.tuning.scale.rootNote=5;else if(kind==='notes')sim.state.tuning.system.noteTunings[0].deviation=8;else sim.state.tuning.system.name='Manual';}if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-tuning-oracle.json.gz',import.meta.url),gzipSync(JSON.stringify({rows,workflows}),{level:9}));console.log({rows:rows.length,workflows:workflows.length});
